/** item id → live-demo wiring. */
export const wire = {
  'progress-ring': (stage) => {
    const r = stage.querySelector('usa-progress-ring');
    stage.querySelector('[data-pr-step]')?.addEventListener('click', () => (r.value = r.value >= 100 ? 8 : Math.min(100, (r.value || 0) + 20)));
  },
  odometer: (stage) => {
    const o = stage.querySelector('usa-odometer');
    stage.querySelector('[data-odo-step]')?.addEventListener('click', () => (o.value = o.value + Math.round(37 + Math.random() * 900)));
  },
  'skeleton-reveal': (stage) => {
    const s = stage.querySelector('usa-skeleton-reveal');
    const b = stage.querySelector('[data-skr-toggle]');
    b?.addEventListener('click', () => {
      s.loading = !s.loading;
      b.textContent = s.loading ? 'Reveal' : 'Reload';
    });
  },
  'masonry-flow': (stage) => {
    const g = stage.querySelector('usa-masonry-flow');
    let only = false;
    stage.querySelector('[data-mf=shuffle]')?.addEventListener('click', () => g.shuffle());
    stage.querySelector('[data-mf=filter]')?.addEventListener('click', () => g.filter((only = !only) ? '.odd' : null));
  },
  stepper: (stage) => {
    const s = stage.querySelector('usa-stepper');
    stage.querySelector('[data-st=next]')?.addEventListener('click', () => (s.value >= s.steps.length - 1 ? (s.value = 0) : s.next()));
    stage.querySelector('[data-st=prev]')?.addEventListener('click', () => s.prev());
  },
  'swipe-deck': (stage) => {
    const d = stage.querySelector('usa-swipe-deck');
    stage.querySelector('[data-sd=like]')?.addEventListener('click', () => (d.top ? d.like() : [0, 1, 2, 3].forEach(() => d.undo())));
    stage.querySelector('[data-sd=nope]')?.addEventListener('click', () => (d.top ? d.nope() : [0, 1, 2, 3].forEach(() => d.undo())));
    stage.querySelector('[data-sd=undo]')?.addEventListener('click', () => d.undo());
  },
  'file-drop': (stage) => {
    const d = stage.querySelector('usa-file-drop');
    stage.querySelector('[data-fd=demo]')?.addEventListener('click', () => d.addFiles([new File(['x'.repeat(48000)], 'hero.jpg'), new File(['y'.repeat(2100)], 'notes.md')]));
  },
  equalizer: (stage) => {
    const eq = stage.querySelector('usa-equalizer');
    stage.querySelectorAll('[data-eq]').forEach((b) => b.addEventListener('click', () => eq.applyPreset(b.dataset.eq)));
  },
  lyrics: (stage) => {
    const p = stage.querySelector('usa-music-player');
    const l = stage.querySelector('usa-lyrics');
    l?.addEventListener('usa:seek', (e) => p?.seek(e.detail.time));
  },
  'bar-chart': (stage) => {
    const c = stage.querySelector('usa-bar-chart');
    const L = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    stage.querySelector('[data-bc]')?.addEventListener('click', () => { const n = 4 + Math.floor(Math.random() * 3); c.data = L.slice(0, n).map((label) => ({ label, value: 4 + Math.round(Math.random() * 24) })); });
  },
  gauge: (stage) => {
    const g = stage.querySelector('usa-gauge');
    stage.querySelector('[data-gg]')?.addEventListener('click', () => { g.value = Math.round(Math.random() * 100); });
  },
  sparkline: (stage) => {
    stage.querySelector('[data-sl]')?.addEventListener('click', () => stage.querySelectorAll('usa-sparkline').forEach((s) => { s.data = Array.from({ length: 7 }, () => 2 + Math.round(Math.random() * 12)); }));
  },
  kpi: (stage) => {
    const k = stage.querySelector('usa-kpi');
    stage.querySelector('[data-kpi]')?.addEventListener('click', () => { k.value = '$' + (30 + Math.random() * 40).toFixed(1) + 'k'; });
  },
  'cart-drawer': (stage) => {
    const c = stage.querySelector('usa-cart-drawer');
    const P = [['tee', 'T-shirt', 24], ['cap', 'Cap', 18], ['mug', 'Mug', 12]];
    stage.querySelector('[data-cd]')?.addEventListener('click', () => { const p = P[Math.floor(Math.random() * P.length)]; c.add({ id: p[0], name: p[1], price: p[2] }); });
  },
  countdown: (stage) => {
    const c = stage.querySelector('usa-countdown');
    stage.querySelector('[data-cdn]')?.addEventListener('click', () => { c.removeAttribute('data-done'); c.setAttribute('seconds', String(10 + Math.random() / 1000)); });
  },
  'message-list': (stage) => {
    const l = stage.querySelector('usa-message-list');
    const R = ['Nice! 🎉', 'Shipping tonight', 'Can you check the Store?', 'LGTM ✅'];
    stage.querySelector('[data-ml]')?.addEventListener('click', () => { l.typing('Ada'); setTimeout(() => l.push({ from: 'Ada', text: R[Math.floor(Math.random() * R.length)] }), 900); });
  },
  'notification-bell': (stage) => {
    const b = stage.querySelector('usa-notification-bell');
    const N = ['New follower: Alan', 'Grace mentioned you', 'Build #812 passed', 'Your order shipped'];
    stage.querySelector('[data-nb]')?.addEventListener('click', () => b.notify({ text: N[Math.floor(Math.random() * N.length)], time: 'now' }));
  },
  presence: (stage) => {
    const S = ['online', 'away', 'busy', 'offline'];
    stage.querySelector('[data-pr]')?.addEventListener('click', () => stage.querySelectorAll('usa-presence').forEach((p) => { p.status = S[(S.indexOf(p.status) + 1) % 4]; }));
  },
  leaderboard: (stage) => {
    const b = stage.querySelector('usa-leaderboard');
    stage.querySelector('[data-lb]')?.addEventListener('click', () => b.rows.forEach((r) => b.setScore(r.name, r.score + Math.round(Math.random() * 300))));
  },
  'xp-bar': (stage) => {
    stage.querySelector('[data-xp]')?.addEventListener('click', () => stage.querySelector('usa-xp-bar').add(35));
  },
  'badge-wall': (stage) => {
    const SEED = '<li data-icon="🏆">First win</li><li data-icon="🔥" data-locked>Streak</li><li data-icon="🎯" data-locked>Sharp</li><li data-icon="🚀" data-locked>Launch</li>';
    stage.querySelector('[data-bw]')?.addEventListener('click', () => {
      const w = stage.querySelector('usa-badge-wall');
      const n = w.badges.find((x) => x.locked);
      if (n) w.unlock(n.name);
      else { const c = w.cloneNode(false); c.innerHTML = SEED; w.replaceWith(c); }
    });
  },
  globe: (stage) => {
    const g = stage.querySelector('usa-globe');
    let i = 0;
    stage.querySelector('[data-gl]')?.addEventListener('click', () => { const ms = g.markers; i = (i + 1) % ms.length; g.flyTo(ms[i].name); });
  },
  'location-card': (stage) => {
    stage.querySelector('[data-lc]')?.addEventListener('click', () => stage.querySelector('usa-location-card').replay());
  },
  field: (stage) => {
    stage.querySelector('[data-fld]')?.addEventListener('click', () => stage.querySelectorAll('usa-field').forEach((f) => f.validate()));
  },
  otp: (stage) => {
    const o = stage.querySelector('usa-otp');
    o.addEventListener('usa:complete', (e) => setTimeout(() => (e.detail.code === '000000' ? o.error() : o.success()), 250));
    stage.querySelector('[data-otp="ok"]')?.addEventListener('click', () => o.fillCode('482913'));
    stage.querySelector('[data-otp="bad"]')?.addEventListener('click', () => o.fillCode('000000'));
  },
  'upload-progress': (stage) => {
    const row = stage.querySelector('usa-upload-progress');
    let v = 10;
    const tick = () => {
      if (!row.isConnected) return;
      v = v >= 100 ? 0 : Math.min(100, v + 6 + Math.round(Math.random() * 8));
      row.setAttribute('status', 'uploading');
      row.value = v;
      setTimeout(tick, v >= 100 ? 1800 : 600);
    };
    setTimeout(tick, 600);
  },
  'chat-composer': (stage) => {
    const c = stage.querySelector('usa-chat-composer');
    const out = stage.querySelector('[data-cc-out]');
    c.addEventListener('usa:send', (e) => {
      out.textContent = `You: ${e.detail.text}`;
      c.busy = true;
      setTimeout(() => { if (c.busy) { c.busy = false; out.textContent += ' → ✓ answered'; c.value = 'Plan a weekend in Kyoto'; } }, 2000);
    });
    c.addEventListener('usa:stop', () => (out.textContent += ' → stopped'));
  },
  'suggestion-chips': (stage) => {
    const sets = [['Summarise this', 'Translate to Chinese', 'Make it shorter', 'Explain like I\'m 5'], ['Add examples', 'Write a haiku', 'Turn into a table'], ['Draft an email', 'Find sources', 'Make it funnier', 'Simplify']];
    let i = 0;
    stage.querySelector('[data-chips]')?.addEventListener('click', () => { i = (i + 1) % sets.length; stage.querySelector('usa-suggestion-chips').setItems(sets[i]); });
  },
  'voice-button': (stage) => {
    const vb = stage.querySelector('usa-voice-button');
    let t = 0;
    const tick = () => {
      if (!vb.isConnected) return;
      t += 1;
      if (vb.listening) vb.level = Math.abs(Math.sin(t / 3) * 0.6 + Math.sin(t / 1.7) * 0.4);
      setTimeout(tick, 90);
    };
    tick();
  },
  'command-palette': (stage) => {
    const p = stage.querySelector('usa-command-palette');
    const out = stage.querySelector('[data-cp-out]');
    p.addEventListener('usa:run', (e) => (out.textContent = `Ran: ${e.detail.label}`));
  },

  shortcut: (stage) => {
    const all = [...stage.querySelectorAll('usa-shortcut')];
    stage.querySelector('[data-sk]')?.addEventListener('click', () => all.forEach((s, i) => setTimeout(() => s.press(), i * 260)));
    let i = 0;
    const tick = () => { if (!stage.isConnected) return; all[i % all.length].press(); i++; setTimeout(tick, 1400); };
    setTimeout(tick, 800);
  },
  'clock-control': (stage) => {
    const seq = stage.querySelector('usa-hydrate');
    const loop = () => { if (!stage.isConnected) return; seq.replay(); seq.timeline?.finished.then(() => setTimeout(loop, 700)); };
    setTimeout(loop, 300);
  },
  hydrate: (stage) => {
    stage.querySelector('[data-hy]')?.addEventListener('click', () => stage.querySelector('usa-hydrate').replay());
  },
  'festival-banner': (stage) => {
    const themes = ['lunar', 'xmas', 'halloween', 'fireworks'];
    const b = stage.querySelector('usa-festival-banner');
    const text = { lunar: 'Happy Lunar New Year 🧧', xmas: 'Merry Christmas 🎄', halloween: 'Happy Halloween 🎃', fireworks: 'Happy New Year 🎆' };
    let i = 0;
    stage.querySelector('[data-fb]')?.addEventListener('click', () => { i = (i + 1) % themes.length; b.lastChild.textContent = text[themes[i]]; b.theme = themes[i]; });
  },
  'sticky-wall': (stage) => {
    const w = stage.querySelector('usa-sticky-wall');
    let i = 0;
    stage.querySelector('[data-sticky-pick]')?.addEventListener('click', () => w?.pick(i++ % (w.notes.length || 1)));
  },
  'sketch-chart': (stage) => {
    stage.querySelector('[data-sketch-new]')?.addEventListener('click', () =>
      stage.querySelectorAll('usa-sketch-chart').forEach((c) => {
        c.setValues(c.values.map(() => 1 + Math.round(Math.random() * 9)));
        c.redraw();
      }));
  },
  'gesture-sticker': (stage) => {
    const s = stage.querySelector('usa-gesture-sticker');
    stage.querySelector('[data-stk-spin]')?.addEventListener('click', () => s?.transformTo({ angle: (s.angle || 0) + 45, scale: s.scale > 1.2 ? 1 : 1.3 }));
  },
  'gyro-card': (stage) => {
    const c = stage.querySelector('usa-gyro-card');
    stage.querySelector('[data-gyro-wobble]')?.addEventListener('click', () => c?.wobble());
  },
  'plugin-store': (stage) => {
    const s = stage.querySelector('usa-plugin-store');
    // showcase: every pack is already registered — a loader that "downloads" for 0.5 s and returns no-op registrars
    if (s) s.loader = () => new Promise((r) => setTimeout(() => r(new Proxy({}, { get: (_, k) => (k === 'then' ? undefined : () => {}) })), 500));
  },
};
